-- Read-only V4A verification. Do not run against Production.
SELECT current_database(), current_user;
SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_name IN ('user','session','account','verification','user_roles','ledger_accounts_financial','ledger_transactions_financial','ledger_entries_financial','idempotency_records_financial','financial_audit_events','reward_funding_sources_financial','reward_programs_financial','reward_backing_allocations_financial','reward_accruals_financial','reward_claims_financial','reward_claim_reservations_financial','settlement_plans_financial','settlement_routes_financial','custody_webhook_events') ORDER BY table_name;
SELECT conrelid::regclass AS table_name,conname,pg_get_constraintdef(oid) AS definition FROM pg_constraint WHERE conrelid::regclass::text IN ('ledger_entries_financial','ledger_transactions_financial','idempotency_records_financial') ORDER BY table_name,conname;
SELECT c.relname,t.tgname,pg_get_triggerdef(t.oid) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE NOT t.tgisinternal AND c.relname IN ('ledger_transactions_financial','ledger_entries_financial','financial_audit_events') ORDER BY c.relname,t.tgname;
SELECT table_name,privilege_type FROM information_schema.role_table_grants WHERE grantee='ace_exchange_runtime' AND table_schema='public' ORDER BY table_name,privilege_type;
SELECT has_table_privilege('ace_exchange_runtime','ledger_entries_financial','DELETE') AS ledger_delete,has_table_privilege('ace_exchange_runtime','financial_audit_events','DELETE') AS audit_delete,has_table_privilege('ace_exchange_runtime','ledger_entries_financial','UPDATE') AS ledger_update;
SELECT to_regprocedure('ace_assert_financial_ledger_balanced(uuid)') AS balance_check_function;
